import React, { useState, useEffect, useRef } from 'react';
import MapDisplay from './MapDisplay';
import './App.css';

function App() {
  const [dailyCustomerCount, setDailyCustomerCount] = useState("");

  const [customers, setCustomers] = useState([]);
  const [selectedCustomerIds, setSelectedCustomerIds] = useState([]);
  const [searchTerm, setSearchTerm] = useState("");

  const [storages, setStorages] = useState([]);
  const [selectedStorageId, setSelectedStorageId] = useState(null);
  const [searchStorageTerm, setSearchStorageTerm] = useState("");

  const [numTrucks, setNumTrucks] = useState("");
  const [productWeight, setProductWeight] = useState("");

  const [optimizationResult, setOptimizationResult] = useState(null);
  const suggestionRef = useRef(null);

  useEffect(() => {
    // fetch customers
    fetch("http://127.0.0.1:5000/customers")
      .then(res => res.json())
      .then(data => {
        setCustomers(data.customers.map(c => ({
          id:       c.CustomerID,
          name:     c.CustomerName,
          address:  c.CustomerAddress,
          location: [c.CustomerLat, c.CustomerLong],
        })));
      })
      .catch(console.error);

    // fetch storages
    fetch("http://127.0.0.1:5000/storages")
      .then(res => res.json())
      .then(data => {
        const list = data.storages.map(s => ({
          id:       s.StorageID,
          name:     s.StorageName,
          address:  s.StorageAddress,
          location: [s.StorageLat, s.StorageLong],
        }));
        setStorages(list);
        if (list.length) setSelectedStorageId(list[0].id);
      })
      .catch(console.error);

    // close dropdowns on outside click
    const onClickOutside = e => {
      if (suggestionRef.current && !suggestionRef.current.contains(e.target)) {
        setSearchTerm("");
        setSearchStorageTerm("");
      }
    };
    document.addEventListener('mousedown', onClickOutside);
    return () => document.removeEventListener('mousedown', onClickOutside);
  }, []);

  // toggle a stop
  const toggleCustomer = id =>
    setSelectedCustomerIds(ids =>
      ids.includes(id) ? ids.filter(x => x !== id) : [...ids, id]
    );

  // remove a stop tag
  const removeCustomer = id =>
    setSelectedCustomerIds(ids => ids.filter(x => x !== id));

  // remove storage tag
  const removeStorage = () =>
    setSelectedStorageId(null);

  // live suggestions
  const customerSuggestions = searchTerm.trim()
    ? customers.filter(c =>
        !selectedCustomerIds.includes(c.id) &&
        c.name.toLowerCase().includes(searchTerm.toLowerCase())
      ).slice(0,5)
    : [];

  const storageSuggestions = searchStorageTerm.trim()
    ? storages.filter(s =>
        s.name.toLowerCase().includes(searchStorageTerm.toLowerCase()) ||
        s.address.toLowerCase().includes(searchStorageTerm.toLowerCase())
      ).slice(0,5)
    : [];

  // submit to backend
  const handleSubmit = async () => {
    const depot = storages.find(s => s.id === selectedStorageId)?.location;
    if (!depot) return alert("Please select a storage first.");
    const stops = selectedCustomerIds.map(id =>
      customers.find(c => c.id === id).location
    );
    const payload = {
      locations:      [depot, ...stops],
      num_vehicles:   numTrucks,
      depot_index:    0,
      daily_customers: dailyCustomerCount,
      total_weight:   productWeight,
    };
    try {
      const res = await fetch("http://127.0.0.1:5000/optimize", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });
      const json = await res.json();
      setOptimizationResult(json);
    } catch (e) {
      console.error(e);
      alert("Failed to optimize routes.");
    }
  };

  // map data
  const routeData    = optimizationResult?.optimized_route?.routes?.[0]?.route || [];
  const defaultCenter = storages.find(s => s.id === selectedStorageId)?.location || [0, 0];

  // Add a new customer with one empty category
  const addCustomer = () => {
    setCustomers([
      ...customers,
      {
        id: Date.now(),
        categories: [
          {
            id: Date.now() + Math.random(),
            weight: '',
            storage: ''
          }
        ]
      }
    ]);
  };

  // Add a new category to a specific customer
  const addCategory = (customerId) => {
    setCustomers(customers.map(c =>
      c.id === customerId
        ? {
            ...c,
            categories: [
              ...c.categories,
              { id: Date.now() + Math.random(), weight: '', storage: '' }
            ]
          }
        : c
    ));
  };

  // Remove a category from a customer
  const removeCategory = (customerId, categoryId) => {
    setCustomers(customers.map(c =>
      c.id === customerId
        ? {
            ...c,
            categories: c.categories.filter(cat => cat.id !== categoryId)
          }
        : c
    ));
  };

  // Update category field
  const updateCategoryField = (customerId, categoryId, field, value) => {
    setCustomers(customers.map(c =>
      c.id === customerId
        ? {
            ...c,
            categories: c.categories.map(cat =>
              cat.id === categoryId
                ? { ...cat, [field]: value }
                : cat
            )
          }
        : c
    ));
  };

  return (
    <div className="container">
    <button className="btn add-row-btn" onClick={addRow}>+ Add</button>
    <div className="table">
      <div className="table-header">
        <span>Customer</span>
        <span>Category</span>
        <span>Weight</span>
        <span>Storage</span>
        <span></span>
      </div>
      {rows.map(row => (
        <div className="table-row" key={row.id}>
          <select
            value={row.customerId}
            onChange={e => updateRow(row.id, "customerId", e.target.value)}
          >
            <option value="">Select Customer</option>
            {customers.map(c => (
              <option key={c.CustomerID} value={c.CustomerID}>
                {c.CustomerName}
              </option>
            ))}
          </select>
          <select
            value={row.category}
            onChange={e => updateRow(row.id, "category", e.target.value)}
          >
            <option value="">Select Category</option>
            {categories.map(cat => (
              <option key={cat} value={cat}>{cat}</option>
            ))}
          </select>
          <input
            type="number"
            placeholder="Weight"
            value={row.weight}
            onChange={e => updateRow(row.id, "weight", e.target.value)}
          />
          <select
            value={row.storageId}
            onChange={e => updateRow(row.id, "storageId", e.target.value)}
          >
            <option value="">Select Storage</option>
            {storages.map(s => (
              <option key={s.StorageID} value={s.StorageID}>
                {s.StorageName}
              </option>
            ))}
          </select>
          <button className="btn remove-btn" onClick={() => removeRow(row.id)}>×</button>
        </div>
      ))}
    </div>
  </div>
);
}

export default App;
